}

.patra-conv-msg.in,
.patra-conv-msg--in {
  flex-direction: row;
  align-self: flex-start;
}

.patra-conv-msg.out,
.patra-conv-msg--out {
  flex-direction: row-reverse;
  align-self: flex-end;
}

.patra-conv-msg.ai,
.patra-conv-msg--ai {
  flex-direction: row;
}

.patra-conv-msg--center {
  max-width: 100%;
  width: 100%;
}

/* Avatar */
.patra-conv-msg .msg-ava :deep(.patra-conv-msg-avatar),
.patra-conv-msg :deep(.patra-conv-msg-avatar) {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 600;
  color: #fff;
  background: linear-gradient(
    135deg,
    var(--patra, #6e56cf),
    var(--patra-deep, #5b45b0)
  );
  align-self: flex-end;
}

.patra-conv-msg.ai :deep(.patra-conv-msg-avatar),
.patra-conv-msg--ai :deep(.patra-conv-msg-avatar) {
  box-shadow: 0 0 12px var(--pm-patra-glow);
}

/* Bubble */
.patra-conv-msg.in :deep(.patra-conv-bubble--user),
.patra-conv-msg.in :deep(.patra-conv-bubble--left),
.patra-conv-msg--in :deep(.patra-conv-bubble--user),
.patra-conv-msg--in :deep(.patra-conv-bubble--left) {
  max-width: 72%;
  padding: 9px 13px;
  border-radius: 14px;
  font-size: 13.5px;
